bool Find(const AnsiString& S, int& Index) const {
        bool found = false;
        int L = 0, H = static_cast<int>(items_.size()) - 1;
        while (L <= H) {
            int I = L + ((H - L) >> 1);
            if (items_[static_cast<size_t>(I)] < S) {
